package cn.workbench;
import org.springframework.stereotype.Component;import org.springframework.transaction.support.TransactionTemplate;import org.springframework.transaction.PlatformTransactionManager;import jakarta.servlet.http.HttpServletRequest;import java.util.*;import java.util.function.Supplier;import java.security.*;import java.nio.charset.StandardCharsets;
@Component public class Writes {
 final Store db;final Jsons json;final TransactionTemplate tx;public Writes(Store d,Jsons j,PlatformTransactionManager m){db=d;json=j;tx=new TransactionTemplate(m);}
 public Object run(HttpServletRequest q,Object body,Supplier<Object> action){long uid=Auth.uid(q);String key=q.getHeader("Idempotency-Key");try{if(key==null||!UUID.fromString(key).toString().equals(key.toLowerCase()))throw new IllegalArgumentException();}catch(Exception e){throw new ApiException(400,"IDEMPOTENCY_KEY_REQUIRED","写入请求必须提供UUID Idempotency-Key");}String hash=sha(q.getMethod()+" "+q.getRequestURI()+" "+q.getSession().getAttribute("scopeId")+" "+q.getSession().getAttribute("delegationId")+" "+json.write(body));try{return tx.execute(status->{var old=db.idempotency(uid,key);if(old!=null)return replay(old,hash);db.reserve(uid,key,hash);Object result=Api.ok(action.get());db.finishIdempotency(uid,key,json.write(result));return result;});}catch(org.springframework.dao.DuplicateKeyException e){var old=db.idempotency(uid,key);if(old==null)throw e;return replay(old,hash);}}
 Object replay(Map<String,Object> old,String hash){if(!hash.equals(old.get("requestHash")))throw new ApiException(409,"IDEMPOTENCY_MISMATCH","同一幂等键不能用于不同请求");if(old.get("responseJson")==null)throw ApiException.conflict();return json.map(String.valueOf(old.get("responseJson")));}
 public void audit(Policy.Actor a,String action,long object){tx.executeWithoutResult(transaction->{String previous=db.lastAudit();if(previous==null)previous="GENESIS";String trace=Api.trace();String hash=sha(previous+"|"+a.uid()+"|"+a.company()+"|"+action+"|"+object+"|"+trace+(a.delegationId()==null?"":"|delegation="+a.delegationId()));db.audit(Records.map("actor",a.uid(),"company",a.company()==null?0:a.company(),"action",action,"object",object,"trace",trace,"previous",previous,"hash",hash,"delegation",a.delegationId()));db.advanceAudit(hash);});}
 public static String sha(String s){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(s.getBytes(StandardCharsets.UTF_8)));}catch(NoSuchAlgorithmException e){throw new IllegalStateException(e);}}
}
